Use ASP.NET Core's **`WebApplicationFactory<T>`** to host your server in-process with an in-memory `HttpClient`. Then drive the MCP protocol over that client.

### Setup

```csharp
// Add these packages to your test project:
// Microsoft.AspNetCore.Mvc.Testing
// xunit (or your preferred test framework)
```

### Example test fixture

```csharp
public class McpIntegrationTests : IClassFixture<WebApplicationFactory<Program>>
{
    private readonly HttpClient _client;

    public McpIntegrationTests(WebApplicationFactory<Program> factory)
    {
        _client = factory.CreateClient();
    }

    [Fact]
    public async Task Initialize_ReturnsCapabilities()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 1,
            method = "initialize",
            @params = new
            {
                protocolVersion = "2025-03-26",
                capabilities = new { },
                clientInfo = new { name = "test-client", version = "1.0" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        Assert.Equal("2.0", body.GetProperty("jsonrpc").GetString());
        Assert.Equal(1, body.GetProperty("id").GetInt32());
        Assert.True(body.GetProperty("result").TryGetProperty("capabilities", out _));
    }

    [Fact]
    public async Task ToolsCall_ExecutesTool()
    {
        var request = new
        {
            jsonrpc = "2.0",
            id = 2,
            method = "tools/call",
            @params = new
            {
                name = "my-tool",
                arguments = new { input = "hello" }
            }
        };

        var response = await _client.PostAsJsonAsync("/mcp", request);

        response.EnsureSuccessStatusCode();
        var body = await response.Content.ReadFromJsonAsync<JsonElement>();
        var result = body.GetProperty("result");
        Assert.False(result.GetProperty("isError").GetBoolean());
    }
}
```

### Key points

| Concern | Approach |
|---|---|
| **No real server** | `WebApplicationFactory` hosts in-process via `TestServer` |
| **Override services** | Use `factory.WithWebHostBuilder(b => b.ConfigureServices(...))` to swap in mocks/fakes |
| **SSE transport** | Read the response stream with `ReadAsStreamAsync()` and parse `text/event-stream` lines |
| **Stateful sessions** | Reuse the same `HttpClient` instance across calls to preserve cookies/headers |
| **Auth** | Configure a test auth handler via `AddAuthentication("Test").AddScheme<TestAuthHandler>(...)` |

### If you use SSE (Streamable HTTP)

```csharp
[Fact]
public async Task Sse_ReceivesEvents()
{
    var request = new HttpRequestMessage(HttpMethod.Post, "/mcp");
    request.Headers.Accept.Add(new("text/event-stream"));
    request.Content = JsonContent.Create(new
    {
        jsonrpc = "2.0", id = 3,
        method = "initialize",
        @params = new { protocolVersion = "2025-03-26", capabilities = new { },
                        clientInfo = new { name = "test", version = "1.0" } }
    });

    var response = await _client.SendAsync(request,
        HttpCompletionOption.ResponseHeadersRead);

    using var stream = await response.Content.ReadAsStreamAsync();
    using var reader = new StreamReader(stream);

    var line = await reader.ReadLineAsync();
    Assert.StartsWith("event:", line);
}
```

This gives you full protocol-level integration tests entirely in-process — fast, deterministic, and no ports to manage.
